        if (_loadingOlder || _allOlderLoaded || _activeChannelId is null) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('[class*=message-list]')?.scrollTop ?? 1");
        if (scrollTop > 50) return;

        _loadingOlder = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _skip, PageSize);
        if (older.Count < PageSize) _allOlderLoaded = true;
        if (older.Count > 0)
        {
            _messages = [..older, ..(_messages ?? [])];
            _skip += older.Count;
            BuildThreadSummaries();
        }
        _loadingOlder = false;
    }

    // ── Threads ──
    private void BuildThreadSummaries()
    {
        if (_messages is null) return;
        _threadSummaries.Clear();

        var replies = _messages.Where(m => m.ReplyToId is not null).ToList();
        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
        {
            _threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt)
            );
        }
    }

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootMessageId = rootMessageId;
        _threadRootMessage = _messages?.FirstOrDefault(m => m.Id == rootMessageId);
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
        _threadReplyText = "";
        _emojiPickerMessageId = null;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessageId = null;
        _threadRootMessage = null;
        _threadMessages = null;
        _threadReplyText = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _activeChannelId is null || _threadRootMessageId is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyText.Trim(), _threadRootMessageId);
        _threadMessages ??= new();
        _threadMessages.Add(reply);
        _messages ??= new();
        _messages.Add(reply);
        _skip++;
        BuildThreadSummaries();
        _threadReplyText = "";
    }

    private async Task HandleThreadKeyDownAsync(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    // ── Reactions ──
    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task AddReactionFromPickerAsync(int messageId, string emoji)
    {
        _emojiPickerMessageId = null;
        await ToggleReactionAsync(messageId, emoji);
    }

    private async Task ToggleReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        // Refresh message list to show updated reactions
        if (_activeChannelId is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _skip > 0 ? _skip : PageSize);
        }
        if (_threadRootMessageId is not null)
        {
            _threadMessages = await ChatService.GetThreadAsync(_threadRootMessageId.Value);
        }
    }

    // ── Helpers ──
    private async Task ScrollToBottomAsync()
    {
        await Task.Yield();
        await JS.InvokeVoidAsync("eval",
            "let el = document.querySelector('[class*=message-list]'); if(el) el.scrollTop = el.scrollHeight;");
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string TruncateDescription(string desc)
    {
        return desc.Length <= 40 ? desc : desc[..37] + "…";
    }
}

/* ── Layout ── */
.chat-container {
    display: flex;
    height: 100vh;
    width: 100vw;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1d1c1d;
    background: #fff;
}

/* ── Sidebar ── */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #3f0e40;
    color: #cfc3cf;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 8px;
    border-bottom: 1px solid #522653;
}

.sidebar-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1.1rem;
    font-weight: 700;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 6px 16px;
    cursor: pointer;
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 4px;
    border-radius: 6px;
    margin: 0 8px;
    position: relative;
    transition: background 0.1s;
}

.channel-item:hover {
    background: #4a154b;
}

.channel-item.active {
    background: #1264a3;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    flex: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.channel-desc {
    width: 100%;
    font-size: 0.75rem;
    opacity: 0.7;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    background: #e01e5a;
    color: #fff;
    border-radius: 10px;
    padding: 0 7px;
    font-size: 0.75rem;
    font-weight: 700;
    line-height: 1.6;
    position: absolute;
    right: 8px;
    top: 6px;
}

/* ── Message Area ── */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    border-right: 1px solid #e1e1e1;
}

.message-area.thread-open {
    max-width: 55%;
}

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e1e1e1;
    flex-shrink: 0;
}

.message-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
}

.channel-description {
    font-size: 0.85rem;
    color: #616061;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #616061;
    font-size: 1.1rem;
}

/* ── Message List ── */
.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

.loading-indicator {
    text-align: center;
    color: #888;
    padding: 12px;
    font-size: 0.85rem;
}

.message-row {
    position: relative;
    padding: 6px 8px;
    border-radius: 6px;
    margin-bottom: 2px;
    transition: background 0.1s;
}

.message-row:hover {
    background: #f8f8f8;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 700;
    font-size: 0.95rem;
}

.timestamp {
    font-size: 0.75rem;
    color: #616061;
}

.message-body {
    font-size: 0.95rem;
    line-height: 1.45;
    white-space: pre-wrap;
    word-break: break-word;
}

/* ── Reactions ── */
.reaction-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    background: #f0f0f0;
    border: 1px solid #ddd;
    border-radius: 12px;
    padding: 1px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.1s;
    line-height: 1.5;
}

.reaction-badge:hover {
    background: #e0e7ff;
    border-color: #99b;
}

/* ── Thread Link ── */
.thread-link {
    background: none;
    border: none;
    color: #1264a3;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 0 0;
    font-weight: 600;
}

.thread-link:hover {
    text-decoration: underline;
}

/* ── Hover Actions ── */
.message-actions {
    position: absolute;
    top: -4px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.1);
    z-index: 10;
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    padding: 4px 6px;
    border-radius: 4px;
    line-height: 1;
}

.action-btn:hover {
    background: #f0f0f0;
}

/* ── Emoji Picker ── */
.emoji-picker {
    position: absolute;
    top: -4px;
    right: 80px;
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
    z-index: 20;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
    line-height: 1;
}

.emoji-option:hover {
    background: #f0f0f0;
}

/* ── Message Input ── */
.message-input-area,
.thread-input-area {
    padding: 12px 20px;
    border-top: 1px solid #e1e1e1;
    display: flex;
    gap: 8px;
    align-items: flex-end;
    flex-shrink: 0;
}

.message-input-area textarea,
.thread-input-area textarea {
    flex: 1;
    resize: none;
    border: 1px solid #ccc;
    border-radius: 6px;
    padding: 8px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input-area textarea:focus,
.thread-input-area textarea:focus {
    border-color: #1264a3;
}

.send-btn {
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 8px 18px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #005e46;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* ── Thread Panel ── */
.thread-panel {
    width: 25%;
    min-width: 260px;
    display: flex;
    flex-direction: column;
    background: #fff;
    border-left: 1px solid #e1e1e1;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #e1e1e1;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 700;
}

.close-thread-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #616061;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-thread-btn:hover {
    background: #f0f0f0;
}

.thread-root-quote {
    padding: 12px 16px;
    border-bottom: 1px solid #e1e1e1;
    background: #fafafa;
    flex-shrink: 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-reply {
    padding: 6px 0;
}

.thread-input-area {
    padding: 12px 16px;
}

